#include <algorithm>
#include <cstddef>
#include <iostream>
#include <print>
#include <string>
#include <utility>

class Buffer {
public:
    Buffer(std::size_t size, int fill) : size_(size), data_(new int[size]) {
        std::fill_n(data_, size_, fill);
    }
    Buffer(const Buffer &other) : size_(other.size_), data_(new int[other.size_]) {
        std::copy_n(other.data_, size_, data_);
    }
    Buffer &operator=(const Buffer &other) {
        Buffer copy(other);
        std::swap(size_, copy.size_);
        std::swap(data_, copy.data_);
        return *this;
    }
    ~Buffer() {
        delete[] data_;
    }

    void set(std::size_t i, int value) {
        data_[i] = value;
    }

    std::string text() const {
        if (size_ == 0) {
            return "пусто";
        }
        std::string s;
        for (std::size_t i = 0; i < size_; ++i) {
            s += (i ? " " : "") + std::to_string(data_[i]);
        }
        return s;
    }

private:
    std::size_t size_;
    int *data_;
};

int main() {
    Buffer a(0, 0), b(0, 0), c(0, 0);
    auto pick = [&](char name) -> Buffer & { return name == 'A' ? a : name == 'B' ? b : c; };
    std::string command;
    char x;
    while (std::cin >> command >> x) {
        if (command == "fill") {
            std::size_t n;
            int v;
            std::cin >> n >> v;
            pick(x) = Buffer(n, v);
        } else if (command == "copy") {
            char y;
            std::cin >> y;
            pick(x) = pick(y);
        } else if (command == "set") {
            std::size_t i;
            int v;
            std::cin >> i >> v;
            pick(x).set(i, v);
        } else {
            std::println("{}: {}", x, pick(x).text());
        }
    }
    return 0;
}

