#include <iostream>
#include <print>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

class Text {
public:
    explicit Text(std::string_view s) : size_(s.size()), data_(new char[s.size()]) {
        std::copy_n(s.data(), size_, data_);
    }
    Text(const Text &other) : size_(other.size_), data_(new char[other.size_]) {
        std::copy_n(other.data_, size_, data_);
    }
    Text &operator=(const Text &other) {
        delete[] data_;
        size_ = other.size_;
        data_ = new char[size_];
        std::copy_n(other.data_, size_, data_);
        return *this;
    }
    ~Text() {
        delete[] data_;
    }

    std::string_view view() const {
        return {data_, size_};
    }

private:
    std::size_t size_;
    char *data_;
};

int main() {
    std::vector<Text> lines;
    std::string command;
    while (std::cin >> command) {
        if (command == "add") {
            std::string word;
            std::cin >> word;
            lines.emplace_back(word);
        } else if (command == "copy") {
            std::size_t to, from;
            std::cin >> to >> from;
            lines[to - 1] = lines[from - 1];
        } else {
            for (std::size_t i = 0; i < lines.size(); ++i) {
                std::println("{}: {}", i + 1, lines[i].view());
            }
        }
    }
    return 0;
}

